import { api } from './api/index.js';
import { uid, showToast } from './utils.js';

/**
 * The whole app's data.
 *
 * semesters: [{ id, schoolYear, label }]                     // e.g. "SY 2025-2026" / "Second Semester"
 * subjects:  [{
 *   id,
 *   semesterId,                                              // which semester it belongs to
 *   course: { code, name, schedule, set, courseYear, instructor, programChair },  // plain strings
 *   students: [{ id, name, sex }],
 *   terms: {
 *     prelims:  { categories: [{ id, name, weight }], assignments: [{ id, name, categoryId, max, date }] },
 *     midterms: { ...same shape... },
 *     finals:   { ...same shape... }
 *   },
 *   scores: { "<studentId>_<assignmentId>": { score, excused } }   // assignment ids are unique across terms
 * }]
 *
 * Exported as a const and always mutated in place — reassigning it would
 * leave every importing module pointing at the old object.
 */
export const TERMS = ['prelims', 'midterms', 'finals'];
export const TERM_LABELS = { prelims: 'Prelims', midterms: 'Midterms', finals: 'Finals' };

export const state = {
  activeSemesterId: null,
  activeSubjectId: null,
  activeTerm: 'prelims',
  semesters: [],
  subjects: []
};

function emptyTerm() {
  return { categories: [], assignments: [] };
}

export function createSemester({ schoolYear = '', label = '' } = {}) {
  return { id: uid(), schoolYear: schoolYear.trim(), label: label.trim() };
}

export function createSubject(course = {}, semesterId = null) {
  return {
    id: uid(),
    semesterId,
    course: {
      code: course.code || '',
      name: course.name || '',
      schedule: course.schedule || '',
      set: course.set || '',
      courseYear: course.courseYear || '',       // e.g. "BIST II-B" (grade sheet)
      instructor: course.instructor || '',       // "Prepared by" on the grade sheet
      programChair: course.programChair || ''     // "Verified by" on the grade sheet
    },
    students: [],
    terms: { prelims: emptyTerm(), midterms: emptyTerm(), finals: emptyTerm() },
    scores: {}
  };
}

export function getActiveSemester() {
  return state.semesters.find(s => s.id === state.activeSemesterId) || null;
}

export function getActiveSubject() {
  return state.subjects.find(s => s.id === state.activeSubjectId) || null;
}

/** The semester a subject sits in (or a blank stand-in). */
export function semesterOf(subject) {
  if (!subject) return { schoolYear: '', label: '' };
  return state.semesters.find(s => s.id === subject.semesterId) || { schoolYear: '', label: '' };
}

/** Subjects in a given semester. */
export function subjectsInSemester(semesterId) {
  return state.subjects.filter(s => s.semesterId === semesterId);
}

/** Distinct school years across all semesters, most recent first-ish (sorted desc). */
export function schoolYears() {
  return [...new Set(state.semesters.map(s => s.schoolYear))].sort().reverse();
}

/** The { categories, assignments } object for the subject + term in focus. */
export function getActiveTermData() {
  const subject = getActiveSubject();
  return subject ? subject.terms[state.activeTerm] : null;
}

/** Short label for switchers and lists, e.g. "ITP 112 · SET A". */
export function subjectLabel(subject) {
  if (!subject) return '—';
  const c = subject.course;
  const head = c.code || c.name || 'Untitled subject';
  return c.set ? `${head} · ${c.set}` : head;
}

/** e.g. "Second Semester · SY 2025-2026". */
export function semesterLabel(sem) {
  if (!sem) return '—';
  const parts = [sem.label || 'Untitled', sem.schoolYear].filter(Boolean);
  return parts.join(' · ');
}

/**
 * Point active* at valid things. Zero semesters / zero subjects are fine states
 * — the UI shows an empty prompt.
 */
export function reconcileState() {
  if (!TERMS.includes(state.activeTerm)) state.activeTerm = 'prelims';

  // active semester
  if (!getActiveSemester()) {
    state.activeSemesterId = state.semesters[0] ? state.semesters[0].id : null;
  }

  // active subject must belong to the active semester
  const inSem = subjectsInSemester(state.activeSemesterId);
  if (!inSem.some(s => s.id === state.activeSubjectId)) {
    state.activeSubjectId = inSem[0] ? inSem[0].id : null;
  }
}

/**
 * Fold pre-semester saves forward: build one semester per distinct
 * (schoolYear, semester) pair found on subjects, blanks -> "Unsorted".
 * Exported for tests; safe to call repeatedly.
 */
export function migrateToSemesters() {
  if (!Array.isArray(state.semesters)) state.semesters = [];
  const key = (sy, lb) => `${sy}�${lb}`;
  const byKey = new Map(state.semesters.map(s => [key(s.schoolYear, s.label), s]));

  for (const subj of state.subjects) {
    if (subj.semesterId && state.semesters.some(s => s.id === subj.semesterId)) {
      // already assigned; still strip stale course fields
      delete subj.course.semester;
      delete subj.course.schoolYear;
      continue;
    }
    const sy = (subj.course.schoolYear || '').trim();
    const lb = (subj.course.semester || '').trim();
    const k = key(sy, lb);
    let sem = byKey.get(k);
    if (!sem) {
      sem = { id: uid(), schoolYear: sy || 'Unsorted', label: lb || 'Unsorted' };
      state.semesters.push(sem);
      byKey.set(k, sem);
    }
    subj.semesterId = sem.id;
    delete subj.course.semester;
    delete subj.course.schoolYear;
  }
}

/* ---------- PERSISTENCE ---------- */

let saveTimer = null;
let pendingToast = null;

/**
 * Coalesces bursts of edits (typing in the score matrix) into one write.
 * Pass a short message to confirm the specific action once the save lands;
 * omit it for silent saves (e.g. switching subject or term).
 */
export function scheduleSave(message = null) {
  pendingToast = message;
  clearTimeout(saveTimer);
  saveTimer = setTimeout(saveState, 400);
}

export async function saveState() {
  const message = pendingToast;
  pendingToast = null;
  try {
    await api.save(state);
    if (message) showToast(message);
  } catch (e) {
    console.error('Save failed', e);
    showToast('Save failed — check the console', 'error');
  }
}

export async function loadState() {
  try {
    const data = await api.load();
    if (data && Array.isArray(data.subjects)) {
      state.subjects = data.subjects;
      state.semesters = Array.isArray(data.semesters) ? data.semesters : [];
      state.activeSemesterId = data.activeSemesterId ?? null;
      state.activeSubjectId = data.activeSubjectId ?? null;
      if (typeof data.activeTerm === 'string') state.activeTerm = data.activeTerm;
    }
  } catch (e) {
    console.error('Load failed — starting with an empty gradebook', e);
  }
  migrateToSemesters();
  reconcileState();
}
